    def get_bg(r, c):
        # Left 5x5 target frame: rows 32..36, cols 11..15
        if 32 <= r <= 36 and 11 <= c <= 15:
            if r in (32, 36) or c in (11, 15):
                return "c"
            return "w"
        # Right 5x5 target frame: rows 26..30, cols 44..48
        if 26 <= r <= 30 and 44 <= c <= 48:
