        if 21 <= r <= 41 and 33 <= c <= 38:
            return "p"
        # Left room floor
        if 21 <= r <= 41 and 9 <= c <= 23:
            return "w"
        # Corridor
        if 30 <= r <= 32 and 24 <= c <= 32:
            return "w"
        # Right room floor
        if 21 <= r <= 41 and 39 <= c <= 53:
            return "w"
        return "g"

    # Find all 3x3 blocks. Their top-left corners (br, bc) are multiples of 3.
    blocks = []
    for br in range(0, 63, 3):
        for bc in range(0, 63, 3):
            corners = [
                grid[br][bc],
                grid[br][bc + 2],
                grid[br + 2][bc],
                grid[br + 2][bc + 2],
            ]
            if corners.count("N") >= 2:
                center = grid[br + 1][bc + 1]
                blocks.append([br, bc, center])

    def draw_state(blocks_list):
        new_grid = [list(row) for row in grid]
        for r in range(63):
            for c in range(64):
                new_grid[r][c] = get_bg(r, c)

        w_block = next((b for b in blocks_list if b[2] == "W"), None)
        b_blocks = [b for b in blocks_list if b[2] == "B"]

        for br, bc, center in blocks_list:
            for dr in range(3):
                for dc in range(3):
                    new_grid[br + dr][bc + dc] = "N"
            new_grid[br + 1][bc + 1] = center

        # Highlight edge of W block if adjacent to a B block
        if w_block:
            wbr, wbc, _ = w_block
            for bbr, bbc, _ in b_blocks:
                if wbr == bbr and wbc + 3 == bbc:
                    for dr in range(3):
                        new_grid[wbr + dr][wbc + 2] = "W"
                elif wbr == bbr and wbc - 3 == bbc:
                    for dr in range(3):
                        new_grid[wbr + dr][wbc] = "W"
                elif wbc == bbc and wbr + 3 == bbr:
                    for dc in range(3):
                        new_grid[wbr + 2][wbc + dc] = "W"
                elif wbc == bbc and wbr - 3 == bbr:
                    for dc in range(3):
                        new_grid[wbr][wbc + dc] = "W"
        return new_grid

