        # Left room floor
        if 21 <= r <= 41 and 9 <= c <= 23:
            return "w"
        # Corridor
        if 30 <= r <= 32 and 24 <= c <= 32:
            return "w"
        # Right room floor
        if 21 <= r <= 41 and 39 <= c <= 53:
            return "w"
        return "g"

