    blocks = []
    for br in range(0, 63, 3):
        for bc in range(0, 63, 3):
            corners = [
                grid[br][bc],
                grid[br][bc + 2],
                grid[br + 2][bc],
                grid[br + 2][bc + 2],
            ]
            if corners.count("N") >= 2:
                center = grid[br + 1][bc + 1]
                blocks.append([br, bc, center])

