                for dc in range(3):
                    new_grid[br + dr][bc + dc] = "N"
            new_grid[br + 1][bc + 1] = center

        # Highlight edge of W block if adjacent to a B block
        if w_block:
            wbr, wbc, _ = w_block
            for bbr, bbc, _ in b_blocks:
                if wbr == bbr and wbc + 3 == bbc:
                    for dr in range(3):
