                            break
                    if (cur_r, cur_c) != (other[0], other[1]):
                        other[0], other[1] = cur_r, cur_c
                        moved_or_pushed = True
            else:
                if is_valid_pos(nbr, nbc):
                    w_block[0], w_block[1] = nbr, nbc
                    moved_or_pushed = True

            new_grid = draw_state(blocks)

            if (wbr, wbc) == (30, 21) and action == "RIGHT":
