            elif (wbr, wbc) == (30, 15) and action == "LEFT":
                should_advance = False
            elif (wbr, wbc) == (30, 24) and action == "LEFT":
                should_advance = False
            elif action == "RIGHT" and not moved_or_pushed:
                should_advance = False
            else:
